create extension if not exists pgcrypto;
do $$begin create type public.plan_type as enum('free','essential','professional');exception when duplicate_object then null;end$$;
do $$begin create type public.appointment_status as enum('pending','confirmed','cancelled','completed');exception when duplicate_object then null;end$$;
create table if not exists public.businesses(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,name text not null,slug text not null unique,description text,whatsapp text,address text,logo_url text,highlight_color text default '#4f46e5',plan public.plan_type not null default 'free',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,price numeric(12,2) not null default 0,duration_minutes int not null default 60 check(duration_minutes between 5 and 720),active boolean not null default true,created_at timestamptz default now());
create table if not exists public.working_hours(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,weekday int not null check(weekday between 0 and 6),enabled boolean default false,start_time time not null default '09:00',end_time time not null default '18:00',break_start time,break_end time,unique(business_id,weekday));
create table if not exists public.appointments(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,service_id uuid not null references public.services(id),client_name text not null,client_phone text not null,appointment_date timestamptz not null,status public.appointment_status not null default 'pending',created_at timestamptz default now());
create index if not exists appt_business_date on public.appointments(business_id,appointment_date);
create or replace function public.plan_service_limit(p public.plan_type) returns int language sql immutable as $$select case p when 'free' then 3 when 'essential' then 10 when 'professional' then 50 end$$;
create or replace function public.plan_appointment_limit(p public.plan_type) returns int language sql immutable as $$select case p when 'free' then 30 when 'essential' then 200 when 'professional' then 2000 end$$;
create or replace function public.validate_appointment() returns trigger language plpgsql security definer set search_path=public as $$declare s services; conflict boolean;begin select * into s from services where id=new.service_id and business_id=new.business_id and active;if not found then raise exception 'Serviço inválido';end if;if new.appointment_date<=now() then raise exception 'Data no passado';end if;select exists(select 1 from appointments a join services os on os.id=a.service_id where a.business_id=new.business_id and a.status<>'cancelled' and a.appointment_date<new.appointment_date+make_interval(mins=>s.duration_minutes) and a.appointment_date+make_interval(mins=>os.duration_minutes)>new.appointment_date) into conflict;if conflict then raise exception 'Horário já ocupado';end if;return new;end$$;
drop trigger if exists appointment_validation on public.appointments;create trigger appointment_validation before insert on public.appointments for each row execute function public.validate_appointment();
alter table public.businesses enable row level security;alter table public.services enable row level security;alter table public.working_hours enable row level security;alter table public.appointments enable row level security;
drop policy if exists business_owner on public.businesses;create policy business_owner on public.businesses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);drop policy if exists business_public on public.businesses;create policy business_public on public.businesses for select using(true);
drop policy if exists service_owner on public.services;create policy service_owner on public.services for all using(exists(select 1 from businesses b where b.id=business_id and b.user_id=auth.uid())) with check(exists(select 1 from businesses b where b.id=business_id and b.user_id=auth.uid()));drop policy if exists service_public on public.services;create policy service_public on public.services for select using(active=true);
drop policy if exists hours_owner on public.working_hours;create policy hours_owner on public.working_hours for all using(exists(select 1 from businesses b where b.id=business_id and b.user_id=auth.uid())) with check(exists(select 1 from businesses b where b.id=business_id and b.user_id=auth.uid()));drop policy if exists hours_public on public.working_hours;create policy hours_public on public.working_hours for select using(true);
drop policy if exists appt_owner_read on public.appointments;create policy appt_owner_read on public.appointments for select using(exists(select 1 from businesses b where b.id=business_id and b.user_id=auth.uid()));drop policy if exists appt_owner_update on public.appointments;create policy appt_owner_update on public.appointments for update using(exists(select 1 from businesses b where b.id=business_id and b.user_id=auth.uid()));drop policy if exists appt_public_insert on public.appointments;create policy appt_public_insert on public.appointments for insert with check(exists(select 1 from services s where s.id=service_id and s.business_id=business_id and s.active=true));
grant select on public.businesses,public.services,public.working_hours to anon,authenticated;grant insert on public.appointments to anon,authenticated;grant select,update on public.appointments to authenticated;grant insert,update,delete on public.businesses,public.services,public.working_hours to authenticated;
